<template><div class="avatar-settings-root"><button type="button" class="avatar-trigger" title="设置头像" @click="open=true"><UserAvatar :key="avatarValue||'empty'" :user-id="userId" :avatar="avatarValue" :name="name" :size="62"/><span class="avatar-edit">✎</span></button><Teleport to="body"><div v-if="open" class="avatar-modal-backdrop" @click.self="open=false"><section class="avatar-modal" role="dialog" aria-modal="true"><header><div><small>PROFILE MEMORY</small><h3>设置个人头像</h3></div><button type="button" class="close" @click="open=false">×</button></header><div class="preview"><UserAvatar :key="`preview-${avatarValue||'empty'}`" :user-id="userId" :avatar="avatarValue" :name="name" :size="112"/><p>JPG / PNG / WEBP，最大 3MB</p></div><p v-if="message" class="message">{{ message }}</p><div class="actions"><label class="upload-button" :class="{disabled:busy}">{{ busy?'处理中…':'选择新头像' }}<input type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy" @change="upload"/></label><button type="button" class="delete-button" :disabled="busy||!avatarValue" @click="remove">删除头像</button></div></section></div></Teleport></div></template>
<script setup lang="ts">
import {ref,watch} from 'vue';import UserAvatar from '@/components/UserAvatar.vue';import {deleteAvatarApi,uploadAvatarApi} from '@/api/profile'
const props=defineProps<{userId:number;name:string;avatar?:string|null}>();const open=ref(false),busy=ref(false),message=ref(''),avatarValue=ref<string|null>(props.avatar||null);watch(()=>props.avatar,v=>avatarValue.value=v||null);function syncLocalUser(avatar:string|null){try{const raw=localStorage.getItem('travel_user');if(!raw)return;const user=JSON.parse(raw);user.avatar=avatar;localStorage.setItem('travel_user',JSON.stringify(user))}catch{}}
async function upload(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];input.value='';if(!file||busy.value)return;busy.value=true;message.value='';try{const r=await uploadAvatarApi(file);if(r.code!==200)throw new Error(r.message||'头像上传失败');avatarValue.value=r.data.avatar;syncLocalUser(r.data.avatar);message.value='头像已更新 ♡'}catch(e){message.value=e instanceof Error?e.message:'头像上传失败'}finally{busy.value=false}}
async function remove(){if(busy.value)return;busy.value=true;message.value='';try{const r=await deleteAvatarApi();if(r.code!==200)throw new Error(r.message||'删除头像失败');avatarValue.value=null;syncLocalUser(null);message.value='已恢复默认头像'}catch(e){message.value=e instanceof Error?e.message:'删除头像失败'}finally{busy.value=false}}
</script>
<style scoped>.avatar-settings-root{display:inline-block}.avatar-trigger{position:relative;padding:0;border:0;border-radius:50%;cursor:pointer;background:transparent}.avatar-edit{position:absolute;right:-1px;bottom:-1px;width:22px;height:22px;display:grid;place-items:center;border:2px solid rgba(255,255,255,.92);border-radius:50%;color:#8d4f70;font-size:10px;background:linear-gradient(135deg,#ffcfe1,#ffedbd)}.avatar-modal-backdrop{position:fixed;inset:0;z-index:99999;display:grid;place-items:center;padding:20px;background:rgba(73,43,61,.26);backdrop-filter:blur(8px)}.avatar-modal{width:min(430px,100%);padding:24px;border:1px solid rgba(255,255,255,.9);border-radius:28px;color:#79465f;background:rgba(255,247,251,.96);box-shadow:0 30px 90px rgba(150,73,111,.22)}.avatar-modal header{display:flex;justify-content:space-between;align-items:flex-start}.avatar-modal small{color:#c47a9c;font-size:9px;letter-spacing:.16em}.avatar-modal h3{margin:4px 0 0;font-size:24px}.close{width:34px;height:34px;border:0;border-radius:50%;cursor:pointer;color:#9a617c;font-size:22px;background:#ffe4ef}.preview{margin:28px 0 20px;display:grid;justify-items:center;gap:12px}.preview p,.message{margin:0;color:#a77a90;font-size:12px}.message{text-align:center}.actions{margin-top:20px;display:grid;grid-template-columns:1fr 1fr;gap:10px}.upload-button,.delete-button{min-height:45px;display:grid;place-items:center;border:0;border-radius:15px;cursor:pointer;color:#75445d;font-weight:800}.upload-button{background:linear-gradient(120deg,#ffcce0,#ffefbd)}.upload-button input{display:none}.delete-button{background:#f9eaf1}.disabled,.delete-button:disabled{opacity:.5;cursor:not-allowed}@media(max-width:520px){.actions{grid-template-columns:1fr}}</style>
